const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const sourceFiles = ['README.md','draft-summary.md','study/protocol.md','evidence/capture-notes.md','evidence/pairs.csv','evidence/reference.csv','evidence/guide.csv','guides/reference-card.txt','guides/reorganized-guide.txt','tools/check-evidence.cjs'];
